+++ b/scripts/check-genai-migration.mjs
@@ -0,0 +1,19 @@
+// Proves the move from @google/generative-ai to @google/genai.
+import { readFileSync } from "node:fs"
+import assert from "node:assert"
+import { GoogleGenAI } from "@google/genai"
+
+const pkg = JSON.parse(readFileSync("package.json", "utf8"))
+assert(pkg.dependencies["@google/genai"], "@google/genai missing")
+assert(!pkg.dependencies["@google/generative-ai"], "old SDK still listed")
+
+const files = ["app/api/ai/chat/route.ts", "lib/ai-client.ts", "lib/ai-utils.ts", "lib/ai-advanced-utils.ts"]
+for (const f of files) {
+  const s = readFileSync(f, "utf8")
+  assert(!/generative-ai|GoogleGenerativeAI|getGenerativeModel|response\.text\(\)/.test(s), `${f} uses old API`)
+  assert(s.includes("@google/genai") && s.includes("models.generateContent"), `${f} not ported`)
+}
+
+const ai = new GoogleGenAI({ apiKey: "x" })
+assert.equal(typeof ai.models.generateContent, "function")
+console.log("ok")

