@@ -0,0 +1,22 @@
+import { GoogleGenAI } from "@google/genai"
+
+/**
+ * Gemini API now stores generateContent requests by default (store=true) for
+ * new paid-tier projects. This app sends user data (profiles, chat), so opt out.
+ */
+export const GEMINI_STORE = false
+
+/** Create a client exposing `generateContent(prompt)` -> `{ response: { text() } }`. */
+export function createModel(apiKey: string, modelName: string) {
+  const ai = new GoogleGenAI({ apiKey })
+  return {
+    async generateContent(prompt: string) {
+      const r = await ai.models.generateContent({
+        model: modelName,
+        contents: prompt,
+        config: { store: GEMINI_STORE },
+      })
+      return { response: { text: () => r.text ?? "" } }
+    },
+  }
+}
